import {withoutAuraDescription,withoutAuraDetails} from './horde-skill-presentation.mjs?v=aura-section3';
import {isSkillEffectDetail} from './skill-effect-style.mjs?v=bonobean1';
import {hordeSkillCards} from './horde-cards-model.mjs';
const $=id=>document.getElementById(id),assetRoot=new URL('./tatari-data/',import.meta.url);
const text=value=>typeof value==='string'?value:value?.en||value?.zh||'';
const image=(src,alt,cls)=>{const img=document.createElement('img');if(src)img.src=new URL(src,assetRoot);img.alt=alt;img.className=cls||'';return img;};
const el=(tag,content,cls)=>{const node=document.createElement(tag);if(content!==undefined)node.textContent=content;if(cls)node.className=cls;return node;};
let data,selected,evolution=1,mode='normal',element=null;

const names={2:'Water',3:'Fire',4:'Grass',5:'Electric',6:'Earth'};
import {searchMatches,minimumStars,calculatedStats,databaseDefaults,compactStat} from './tatari-model.mjs';

function roster(){const entries=data.units.filter(u=>(!element||u.element===element)&&searchMatches(u,$('tatari-search').value)).flatMap(u=>u.forms.filter(f=>f.evolution===1).map(form=>({u,form}))).sort((a,b)=>a.form.evolution-b.form.evolution||a.u.id-b.u.id);$('roster-count').textContent=entries.length+' Tatari · Tier I · v'+data.version;$('tatari-roster').replaceChildren(...entries.map(({u,form})=>{const button=el('button',undefined,'roster-card');button.type='button';button.dataset.petId=u.id;button.dataset.tier=form.evolution;button.setAttribute('aria-label','Show '+text(form.name)+' · tier '+form.evolution);button.setAttribute('aria-pressed',String(u.id===selected?.id));button.append(image(u.elementImage,names[u.element]||'Unknown element','roster-element'),image(u.roleImage,text(u.role),'roster-role'),image(form.portrait,text(form.name),'roster-portrait'),el('span',text(form.name)),el('small','T'+form.evolution,'roster-tier'));button.onclick=()=>{selected=u;evolution=form.evolution;render();roster();updateLink();};return button;}));if(!entries.length)$('tatari-roster').append(el('p','No Tatari matches. Try another name or clear the element filter.','roster-empty'));}
function updateLink(){const url=new URL(location.href);url.searchParams.set('tatari',selected.id);url.searchParams.set('tier',evolution);url.searchParams.set('skills',mode);history.replaceState(null,'',url);}
function starDisplay(n){const box=el('div',undefined,'star-display');if(Number.isInteger(n)&&n>0&&n<=84)box.append(image('stars/'+String(n).padStart(2,'0')+'.png',n+' stars','star-level-image'));else if(n===null)box.textContent='Not recorded';return box;}
function stars(n){return n===null?'Not recorded':n===0?'0 stars':n<=6?'★'.repeat(n):n+' ★';}
function render(){const f=selected.forms.find(f=>f.evolution===evolution),min=minimumStars(selected,f);$('evolution-list').replaceChildren(...selected.forms.map(form=>{const button=el('button',undefined,'evolution-button');button.type='button';button.setAttribute('aria-pressed',String(form.evolution===evolution));button.setAttribute('aria-label',text(form.name)+' · tier '+form.evolution);button.append(image(form.playerhead,text(form.name)),el('span',text(form.name)));button.onclick=()=>{evolution=form.evolution;render();roster();updateLink();};return button;}));const max=f.evolution===Math.max(...selected.forms.map(f=>f.evolution));const evoArt=el('div',undefined,'evo-requirement-art');evoArt.append(image('images/evo.png','Evolution badge','evo-badge'));if(!max)evoArt.append(starDisplay(f.trial?.requiredStars??null));$('next-evolution').replaceChildren(evoArt,el('span',max?'Already at max tier':f.trial?.requiredStars!=null?'Reach Star Lv.'+f.trial.requiredStars+' to Evo':'Evolution requirement not recorded'));const title=el('div',undefined,'profile-heading'),badges=el('div',undefined,'profile-badges');badges.append(image(selected.elementImage,names[selected.element]),image(selected.roleImage,text(selected.role)));title.append(image(selected.elementImage,names[selected.element],'name-element'),el('h1',text(f.name)),image(selected.roleImage,text(selected.role),'name-role'));const stats=el('div',undefined,'base-stats');const defaults=databaseDefaults(selected,f);if(defaults.stars!==null&&defaults.foodStage!==null){const values=calculatedStats(data,selected,f,defaults),feed=selected.feedingStages.find(r=>r.stage===defaults.foodStage);for(const a of ['ATK','HP','DEF']){const tile=el('div',undefined,'stat-tile'),grade=({0:'E',5:'D',10:'C',25:'B',40:'A',50:'S',55:'SS',60:'SSS'})[feed[a+'PR']],art=el('div',undefined,'food-stat-art');if(grade)art.append(image('food-stats/'+grade+a.toLowerCase()+'.png',grade+' '+a+' food grade','food-stat-icon'));const value=el('strong',compactStat(values[a]),'food-stat-value');value.setAttribute('aria-label',a+' '+compactStat(values[a]));art.append(value);tile.append(art);stats.append(tile);}}else stats.append(el('p','Evolution requirements not recorded.','baseline'));const portraitCard=el('div',undefined,'portrait-card tier-'+f.evolution);portraitCard.append(image('images/tier-'+f.evolution+'.png','','portrait-card-background'),image(f.portrait,text(f.name),'detail-portrait'),starDisplay(min));$('tatari-profile').replaceChildren(portraitCard,title,el('p',text(f.lore)||text(f.description),'profile-lore'),stats,el('p','Stats based on level 500 Tatari with their evolution requirements applied.','food-note'));renderSkills();}
function renderSkills(){
 for(const m of ['normal','horde','trial']){const button=$(m+'-skills');button.setAttribute('aria-selected',String(mode===m));button.tabIndex=mode===m?0:-1;}
 $('skill-panel').setAttribute('aria-labelledby',mode+'-skills');const f=selected.forms.find(f=>f.evolution===evolution);
 $('skill-panel').querySelector('.horde-note')?.remove();if(mode==='trial'){renderEvolutionTrial();return}
 $('skill-list').classList.remove('evolution-trial-list');
 $('skill-list').classList.add('normal-tier-list');
 const entries=mode==='normal'?selected.forms.map(form=>({form,skills:form.skills.normal.filter(s=>!text(s.name).includes('不用翻译'))})):hordeSkillCards(f).map(card=>({form:f,...card}));
 $('skill-list').dataset.cardCount=entries.length;
 $('skill-list').replaceChildren(...entries.map(({form,skills,label})=>{const card=el('article',undefined,'skill-card horde-skill-card normal-tier-card'),first=skills[0];
 if(mode==='normal'){card.dataset.tier=form.evolution;card.setAttribute('aria-current',String(form.evolution===evolution));card.setAttribute('aria-label',text(form.name)+' · tier '+form.evolution+' skills');}
 const heading=el('div',undefined,'skill-heading');heading.append(el('h2',first?text(first.name):'Skills not recorded'),el('span',mode==='normal'?'Tier '+form.evolution:label,'horde-skill-level'));card.append(heading);
 const description=el('p',undefined,'skill-description');if(mode==='normal')description.append(el('strong',text(form.name),'skill-form-name'));for(const [i,s] of skills.entries()){if(i)description.append(el('strong',text(s.name),'skill-form-name'));description.append(document.createTextNode(mode==='horde'?withoutAuraDescription(s.description):text(s.description)));}card.append(description);
 const rows=el('div',undefined,'horde-detail-rows');for(const [i,s] of skills.entries()){if(i)rows.append(el('strong',text(s.name),'extra-skill-heading'));for(const d of mode==='horde'?withoutAuraDetails(s.details):s.details){if(mode==='horde'&&label==='Regular'&&text(d.title)==='Arena Factor')continue;const row=el('div',undefined,'horde-detail-row');row.classList.toggle('skill-effect-slot',isSkillEffectDetail(d,text(d.title)));if(d.type==='Effect'||d.value===null){row.append(el('strong',text(d.title)),el('span',text(d.text)));}else row.append(el('strong',[text(d.title),text(d.text)].filter(Boolean).join(' ')));rows.append(row);}}card.append(rows);return card;}));
 $('skill-panel').querySelector('.horde-note')?.remove();if(mode==='horde')$('skill-panel').append(el('p','Horde skill availability depends on evolution and Horde progression.','horde-note'));
}
for(const m of ['normal','horde','trial']){$(m+'-skills').onclick=()=>{mode=m;renderSkills();updateLink();};$(m+'-skills').onkeydown=e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const tabs=['normal','horde','trial'];mode=e.key==='Home'?'normal':e.key==='End'?'trial':tabs[(tabs.indexOf(mode)+(e.key==='ArrowRight'?1:2))%3];renderSkills();$(mode+'-skills').focus();updateLink();}};}
$('tatari-search').oninput=()=>{if(data)roster();};
try{const response=await fetch(new URL('roster.json?v=bonobean1',assetRoot));if(!response.ok)throw Error('Tatari data could not be loaded.');data=await response.json();const params=new URLSearchParams(location.search);selected=data.units.find(u=>u.id===Number(params.get('tatari')))||data.units.find(u=>u.id===11)||data.units[0];evolution=selected.forms.some(f=>f.evolution===Number(params.get('tier')))?Number(params.get('tier')):1;mode=['normal','horde','trial'].includes(params.get('skills'))?params.get('skills'):'normal';for(const id of [3,4,6,5,2]){const unit=data.units.find(u=>u.element===id),button=el('button');button.type='button';button.setAttribute('aria-label','Filter '+names[id]);button.setAttribute('aria-pressed','false');button.append(image(unit.elementImage,names[id]));button.onclick=()=>{element=element===id?null:id;[...$('element-filters').children].forEach(b=>b.setAttribute('aria-pressed',String(b===button&&element!==null)));roster();};$('element-filters').append(button);}roster();render();}catch(error){$('database-status').textContent=error.message;$('database-status').setAttribute('role','alert');}

function renderEvolutionTrial(){const list=$('skill-list');list.classList.remove('normal-tier-list');list.classList.add('evolution-trial-list');list.replaceChildren();const forms=[...selected.forms].sort((a,b)=>a.evolution-b.evolution);for(let i=0;i<forms.length-1;i++){const from=forms[i],to=forms[i+1],card=el('article',undefined,'evolution-trial-step'),heading=el('div',undefined,'trial-step-heading');card.classList.toggle('trial-next-evolution',to.evolution===evolution+1);card.setAttribute('aria-current',String(to.evolution===evolution+1));const name=el('h2',undefined,'trial-target-name');name.append(image(to.playerhead,text(to.name),'trial-target-head'),el('span',text(to.name)));name.title=text(from.name)+' → '+text(to.name);const required=from.trial?.requiredStars,stars=el('span',undefined,'trial-stars');if(Number.isInteger(required)){stars.setAttribute('aria-label',required+' stars required');stars.append(image('stars/'+String(required).padStart(2,'0')+'.png',required+' stars','trial-required-stars'))}else stars.textContent='Stars not recorded';const tierLabel=el('span','Tier '+to.evolution,'trial-target-tier');name.append(tierLabel);heading.append(name,stars);card.append(heading);const quests=from.trial?.quests||[];if(quests.length){const rows=el('div',undefined,'trial-requirement-rows');for(const quest of quests){const row=el('div',undefined,'trial-requirement-row'),icons=el('div',undefined,'trial-requirement-icons');for(const src of trialRequirementIcons(quest,from))icons.append(image(src,'','trial-requirement-icon'));row.append(icons,el('span',text(quest.text)));rows.append(row)}card.append(rows)}else card.append(el('p','Trial requirements not recorded.'));list.append(card)}if(forms.length<2)list.append(el('p','No further evolution recorded.'));}

function trialRequirementIcons(quest,form){if(quest.icons?.length)return quest.icons;const value=text(quest.text).toLowerCase();if(quest.alternatives)return ['/guide-assets/fishing/rod1.png','/guide-assets/zobo-shooter.png'];if(/fishing|fish.*rod/.test(value))return ['/guide-assets/fishing/rod1.png'];if(/zobo shooter|bullet/.test(value))return ['/guide-assets/zobo-shooter.png'];if(/pinball/.test(value))return ['/guide-assets/fishing/pinball.png'];if(/energy drink|goldrush|gold rush/.test(value))return ['/guide-assets/goldrush/drink.png'];if(/badge/.test(value))return ['images/badge-'+({2:1001,3:2001,4:3001,6:4001,5:5001}[selected.element])+'.webp'];if(/b quality/.test(value))return ['food-stats/Bhp.png'];return [form.playerhead||form.portrait];}
